import{_ as r}from"./chunks/Audio.COine8Wh.js";import{c as i,o,j as t,G as a,ae as s,a as n}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"MODIFYING THE SCOPE OF TARIFFS ON THE GOVERNMENT OF BRAZIL","description":"","frontmatter":{"legisId":"2025-11-20-modifying-the-scope-of-tariffs-on-the-government-of-brazil","title":"MODIFYING THE SCOPE OF TARIFFS ON THE GOVERNMENT OF BRAZIL","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/11/modifying-the-scope-of-tariffs-on-the-government-of-brazil/","publishDate":"2025-11-20T16:37:03-05:00"},"headers":[],"relativePath":"executive-orders/2025-11-20-modifying-the-scope-of-tariffs-on-the-government-of-brazil.md","filePath":"executive-orders/2025-11-20-modifying-the-scope-of-tariffs-on-the-government-of-brazil.md"}'),l={name:"executive-orders/2025-11-20-modifying-the-scope-of-tariffs-on-the-government-of-brazil.md"},h=Object.assign(l,{setup(f){return(d,e)=>(o(),i("div",null,[e[0]||(e[0]=t("h1",{id:"modifying-the-scope-of-tariffs-on-the-government-of-brazil",tabindex:"-1"},[n("MODIFYING THE SCOPE OF TARIFFS ON THE GOVERNMENT OF BRAZIL "),t("a",{class:"header-anchor",href:"#modifying-the-scope-of-tariffs-on-the-government-of-brazil","aria-label":'Permalink to "MODIFYING THE SCOPE OF TARIFFS ON THE GOVERNMENT OF BRAZIL"'},"​")],-1)),a(r),e[1]||(e[1]=s('<p>Published on Thursday, November 20, 2025</p><p><strong>Headline:</strong> U.S. eases tariffs on some Brazilian agricultural imports amid ongoing negotiations.</p><p><strong>Why it matters:</strong> The order narrows U.S. trade restrictions against Brazil, lifting extra tariffs on select agricultural products as talks progress toward resolving national security concerns.</p><p><strong>What the order does:</strong></p><ul><li>Removes the 40% additional tariff from certain Brazilian agricultural imports.</li><li>Updates the list of exempt products in Annex I and modifies the U.S. Harmonized Tariff Schedule.</li><li>Orders refunds for duties already collected on newly exempt products.</li><li>Directs the Secretary of State and other agencies to monitor the situation and enforce the updated order.</li></ul><p><strong>Who it affects:</strong></p><ul><li>U.S. importers of Brazilian agricultural goods.</li><li>Brazilian agricultural exporters.</li><li>Relevant U.S. federal agencies.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Lower prices or greater availability for certain Brazilian agricultural products in the U.S.</li><li>Reduced costs for businesses importing exempted Brazilian goods.</li></ul><p><strong>Context:</strong> The modification responds to initial progress in U.S.-Brazil negotiations after tariffs were imposed in response to perceived national security threats.</p><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/11/modifying-the-scope-of-tariffs-on-the-government-of-brazil/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/11/modifying-the-scope-of-tariffs-on-the-government-of-brazil/</a></p>',11))]))}});export{g as __pageData,h as default};
